class Command(BaseCommand):
    help = "Seeds the database with 54 high-quality IT products, accessories, and repair services including associated image files."

    def handle(self, *args, **options):
        self.stdout.write("Checking category existence...")
        categories = {}
        for cat in Category.objects.all():
            categories[cat.id] = cat

        # Fallback category creation or validation
        required_ids = {p['category_id'] for p in PRODUCTS_DATA}
        missing_ids = required_ids - set(categories.keys())
        if missing_ids:
            self.stdout.write(self.style.ERROR(f"Missing category IDs in database: {missing_ids}"))
            self.stdout.write("Please run migrations or seed categories first.")
            return

        today_str = date.today().strftime('%Y-%m-%d')
        target_media_dir = os.path.join(settings.MEDIA_ROOT, 'store_products', today_str)
        os.makedirs(target_media_dir, exist_ok=True)

        self.stdout.write(f"Seeding products... Target media folder: {target_media_dir}")
        created_count = 0

        for item in PRODUCTS_DATA:
            cat_id = item['category_id']
            category = categories[cat_id]
            title = item['title']
            brand = item['brand']
            sku = item['sku']
            short_desc = item['short_description']
            desc = item['description']
            original_price = item['original_price']
            selling_price = item['selling_price']
            stock_qty = item['stock_qty']
            is_featured = item.get('is_featured', False)
            is_new_arrival = item.get('is_new_arrival', False)
            is_best_seller = item.get('is_best_seller', False)
            rating = item.get('rating', Decimal('0.0'))
            reviews_count = item.get('reviews_count', 0)

            # Specs
            processor = item.get('processor', '')
            ram = item.get('ram', '')
            storage = item.get('storage', '')
            graphics = item.get('graphics', '')
            display = item.get('display', '')
            battery = item.get('battery', '')
            warranty = item.get('warranty', '')

            # Image handling
            src_image_path = None
            if cat_id == 4:
                # CCTV products has dome and bullet options
                img_opts = BASE_IMAGE_MAP[4]
                if 'Bullet' in title:
                    src_image_path = img_opts['bullet']
                else:
                    src_image_path = img_opts['dome']
            else:
                src_image_path = BASE_IMAGE_MAP.get(cat_id)

            relative_image_path = None
            if src_image_path and os.path.exists(src_image_path):
                filename = f"{slugify(title)}.png"
                dst_image_path = os.path.join(target_media_dir, filename)
                try:
                    shutil.copy2(src_image_path, dst_image_path)
                    relative_image_path = f"store_products/{today_str}/{filename}"
                except Exception as e:
                    self.stdout.write(self.style.WARNING(f"Failed to copy image for {title}: {e}"))
            else:
                self.stdout.write(self.style.WARNING(f"Source image not found for category {cat_id}: {src_image_path}"))

            slug = slugify(title)
            # Ensure unique slug in database if necessary
            base_slug = slug
            counter = 1
            while Product.objects.filter(slug=slug).exists():
                slug = f"{base_slug}-{counter}"
                counter += 1

            product, created = Product.objects.update_or_create(
                sku=sku,
                defaults={
                    "category": category,
                    "title": title,
                    "slug": slug,
                    "brand": brand,
                    "short_description": short_desc,
                    "description": desc,
                    "original_price": original_price,
                    "selling_price": selling_price,
                    "stock_qty": stock_qty,
                    "image": relative_image_path,
                    "is_active": True,
                    "is_featured": is_featured,
                    "is_new_arrival": is_new_arrival,
                    "is_best_seller": is_best_seller,
                    "processor": processor,
                    "ram": ram,
                    "storage": storage,
                    "graphics": graphics,
                    "display": display,
                    "battery": battery,
                    "warranty": warranty,
                    "rating": rating,
                    "reviews_count": reviews_count,
                }
            )

            if created:
                created_count += 1

        self.stdout.write(self.style.SUCCESS(f"Successfully seeded database. Created {created_count} new products."))
